6863\u89c4\u7ea6\u53ef\u8fd0\u884c\uff1b\u82e5\u8fd0\u884c\u73af\u5883\u9700\u9884\u88c5 numpy/torch\uff08\u5f53\u524d\u73af\u5883\u7f3a\u5931\u4e14\u65e0\u6cd5\u8054\u7f51\u5b89\u88c5\uff09\uff0c\u7531\u6267\u884c\u65b9\u6ee1\u8db3\u3002\n4. \u6a21\u578b\u89c4\u6a21\u6309 CPU \u53cb\u597d\u8bbe\u8ba1\uff08\u9aa8\u5e72\u4ec5 linear/DLinear\uff09\uff0c\u4e0d\u8ffd\u6c42\u8bba\u6587\u7ea7\u5927\u6a21\u578b\u3002\n\n**C. \u786e\u5b9a\u7684\u4e0d\u786e\u5b9a\u9879**\n1. CycleNet \u7684 lag \u76f8\u4f4d\u8ba1\u7b97\u3001\u5faa\u73af\u7279\u5f81\u4e0e\u5f52\u4e00\u5316\u4ea4\u4e92\u7684\u590d\u73b0\u7ec6\u8282\u65e0\u6cd5\u79bb\u7ebf\u6838\u5b9e \u2192 \u4ee5\u672c\u6587\u6863\u9ed8\u8ba4\u503c\uff08L=0\uff09\u4e3a\u57fa\u5e76\u7eb3\u5165\u654f\u611f\u6027\u5b9e\u9a8c\uff08AB2\uff09\u3002\n2. \u5408\u6210\u6570\u636e\uff08\u6b63\u5f26+\u9ad8\u65af\u566a\u58f0\uff09\u4e0d\u80fd\u5b8c\u5168\u4ee3\u8868\u771f\u5b9e\u65f6\u5e8f\u7684\u5f02\u65b9\u5dee\u566a\u58f0/\u65e5\u5386\u6548\u5e94 \u2192 \u7ed3\u8bba\u5916\u63a8\u8fb9\u754c\u89c1 \u00a710\u3002\n3. \u516c\u5171\u57fa\u51c6\u6570\u636e\u662f\u5426\u53ef\u5f97\u672a\u5b9a \u2192 O4 \u4e3a\u53ef\u9009\u9a8c\u8bc1\u5206\u652f\u3002\n4. \u65e0 GPU \u65f6\u6df1\u5ea6\u9aa8\u5e72\uff08PatchTST \u7ea7\uff09\u4e0d\u53ef\u884c\uff0c\u53ef\u80fd\u4f4e\u4f30 CycleNet \u4e0e\u5f3a\u9aa8\u5e72\u7ed3\u5408\u7684\u589e\u76ca\u3002\n\n## 2. \u7814\u7a76\u95ee\u9898\u4e0e\u76ee\u6807\n- **RQ1**\uff1aCycleNet \u662f\u5426\u80fd\u6bd4\u65e0\u663e\u5f0f\u5468\u671f\u5efa\u6a21\u7684\u57fa\u7ebf\u66f4\u51c6\u786e\u5730\u9884\u6d4b\u5468\u671f\u65f6\u5e8f\uff1f\uff08\u4e3b\u5bf9\u7167\uff09\n- **RQ2**\uff1a\u9884\u6d4b\u65f6\u957f H \u4e0e\u5468\u671f\u957f\u5ea6 w \u7684\u5173\u7cfb\uff08H<w vs H>w\uff09\u5982\u4f55\u5f71\u54cd CycleNet \u76f8\u5bf9\u57fa\u7ebf\u7684\u4f18\u52bf\uff1f\n- **RQ3**\uff1a\u5faa\u73af\u7279\u5f81\u662f\u5426\u5fc5\u987b\u53ef\u5b66\u4e60/\u8054\u5408\u8bad\u7ec3\uff1f\u5468\u671f\u957f\u5ea6\u3001lag \u7b49\u8d85\u53c2\u7684\u654f\u611f\u6027\u5982\u4f55\uff1f\n- \u6210\u529f\u6807\u51c6\uff1a\u5728\u5408\u6210\u6570\u636e\u4e0a\uff0cCycleNet \u7684 test MSE/MAE \u5728\u591a\u6570\u5355\u5143\u683c\u4f4e\u4e8e NoCycle \u9aa8\u5e72\u3001DLinear\u3001Seasonal-naive\u3001Persistent\uff0c\u4e14 w \u6b63\u786e\u65f6\u6700\u4f18\uff1b\u7a33\u5b9a\u6027\u7528\u591a seed \u7684\u5747\u503c\u00b1std \u5224\u65ad\u3002\n\n## 3. \u6570\u636e\u8bbe\u8ba1\uff08\u5408\u6210\u751f\u6210\u5668\u89c4\u683c\uff09\n\n### 3.1 \u8bb0\u53f7\uff08\u5168\u6587\u4e00\u81f4\uff09\n- \u5355\u6761\u65f6\u5e8f\u957f\u5ea6 T\uff1b\u5468\u671f\u957f\u5ea6 w\uff1b\u8f93\u5165\u957f\u5ea6 P\uff1b\u9884\u6d4b\u65f6\u957f H\uff1b\u901a\u9053\u6570 D\u3002\n- \u7edd\u5bf9\u65f6\u95f4 n\u2208{0,\u2026,T\u22121}\uff1b\u5f53\u524d\u6700\u540e\u89c2\u6d4b\u65f6\u523b t\uff1b\u672a\u6765\u7d22\u5f15 j=1..H\uff08\u5bf9\u5e94\u65f6\u523b t+j\uff09\u3002\n- \u76f8\u4f4d\u51fd\u6570 \u03c6(n) = (n + L) mod w\uff0cL \u4e3a lag \u504f\u79fb\uff0c\u9ed8\u8ba4 L=0\u3002\n- \u5f52\u4e00\u5316\uff1a\u6bcf\u6761\u5e8f\u5217\u53d6\u5176 **train \u6bb5**\u7684 \u03bc,\u03c3 \u505a z-score\uff1b\u9884\u6d4b\u53cd\u5f52\u4e00\u5316\u56de\u539f\u5c3a\u5ea6\u518d\u7b97\u6307\u6807\u3002\n\n### 3.2 \u751f\u6210\u5668\u4f2a\u4ee3\u7801\uff08\u5b9e\u73b0\u8bed\u8a00\u65e0\u5173\uff0cPython \u7ea6\u5b9a\uff09\n```\ndef gen_series(seed, w, n_cycles, D, SNR, multi, drift, rng):\n    T = n_cycles * w                       # \u4f8b\u5982 w=24\u21922880\uff0cw=168\u21924032\n    n = arange(T)\n    X = zeros(T, D)\n    for c in range(D if multi else 1):\n        phase  = rng.uniform(0, w)                         # \u6bcf\u901a\u9053\u968f\u673a\u76f8\u4f4d\n        amp    = rng.uniform(0.5, 1.5)\n        trend  = 0.0\n        if drift: trend = slope * n                        # \u7ebf\u6027\u6f02\u79fb\uff0cslope\u2208{0.001,0.01}(\u5f52\u4e00\u5316\u540e)\n        X[:,c] = amp * sin(2*pi*(n + phase)/w) \\\n               + (0.3*amp)*sin(4*pi*(n+phase)/w)           # \u57fa\u9891+\u4e00\u6b21\u8c10\u6ce2\n        if not multi: break                                # \u5355\u53d8\u91cf D=1\n    noise = rng.normal(0, amp, (T,D)) / SNR                 # SNR=\u4fe1\u53f7\u5e45\u5ea6/\u566a\u58f0\u03c3\n    return X + noise\n```\n- \u56e0\u5b50\uff1aw\u2208{24,168}\uff1bSNR\u2208{0.1,1.0}\uff08`SNR=\u4fe1\u53f7\u5e45\u5ea6/\u566a\u58f0\u03c3`\uff0c0.1 \u9ad8\u566a\u58f0\u30011.0 \u4f4e\u566a\u58f0\uff09\uff1b\u591a\u53d8\u91cf D\u2208{1,8}\uff1bdrift\u2208{False,True}\u3002\n- \u6570\u636e\u8d28\u91cf\u68c0\u67e5\uff08\u8bbe\u8ba1\u89c4\u7ea6\uff09\uff1a\u751f\u6210\u540e\u505a\u4e00\u6b21 FFT \u5cf0\u503c\u9a8c\u8bc1\u5468\u671f\u2248w\uff0c\u786e\u4fdd\u751f\u6210\u5668\u6b63\u786e\uff08\u68c0\u67e5\u9879\uff0c\u4e0d\u6784\u6210\u5b9e\u9a8c\u7ed3\u8bba\uff09\u3002\n\n### 3.3 \u5212\u5206\uff08\u65e0\u6cc4\u6f0f\u3001\u6240\u6709\u65b9\u6cd5\u5171\u7528\uff09\n- \u6309\u65f6\u95f4\u987a\u5e8f\uff1atrain \u6bb5 70%\uff08\u7528\u4e8e \u03bc,\u03c3 \u4e0e\u8bad\u7ec3\uff09\u3001val \u6bb5 10%\uff08\u9009\u6a21/\u65e9\u505c\uff09\u3001test \u6bb5 20%\uff08\u4ec5\u6700\u7ec8\u8bc4\u4f30\uff09\u3002\n- \u8bad\u7ec3\u7a97\u53e3\uff1a\u5728 train \u6bb5\u5185\u6309 **stride=H** \u6ed1\u52a8\u53d6 (\u8f93\u5165 P, \u6807\u7b7e H)\uff0c\u8f93\u5165 `x_{t-P+1:t}`\u3001\u6807\u7b7e `x_{t+1:t+H}`\uff1b\u4efb\u4f55\u7a97\u53e3\u4e0d\u8de8\u6bb5\u8fb9\u754c\u3002\n- P \u8bbe\u5b9a\uff1aP = max(2w, 256)\uff08w=24\u2192P=256\uff1bw=168\u2192P=336\uff09\uff0c\u4fdd\u8bc1\u81f3\u5c11\u542b\u4e24\u4e2a\u5b8c\u6574\u5468\u671f\u3002\n\n## 4. \u6a21\u578b\u89c4\u683c\uff08CycleNet\uff09\n### 4.1 \u7ec4\u4ef6\n- \u5faa\u73af\u67e5\u627e\u8868 C\u2208R^{w\u00d7D}\uff08\u53ef\u5b66\u4e60\uff0c\u7528 \u03c6 \u7d22\u5f15\uff1bD \u901a\u9053\u5404\u81ea\u4e00\u4e2a bias \u5411\u91cf\uff09\u3002\n- \u9aa8\u5e72 B\uff1a\u9ed8\u8ba4**\u7ebf\u6027\u6b8b\u5dee\u9aa8\u5e72**\uff08B_lin\uff1a`R_future = W@R + b`\uff0cW\u2208R^{H\u00d7P}\uff0c\u6309\u901a\u9053\u5171\u4eab\uff0c\u8bb0\u4f5c linear\uff09\uff0c\u53d8\u4f53 **DLinear**\uff08B_DL\uff1a\u5bf9 R \u505a\u5747\u503c\u79fb\u52a8\u5e73\u5747\u5206\u89e3\u4e3a\u8d8b\u52bf+\u5b63\u8282\uff0c\u5404\u63a5\u4e00\u4e2a\u7ebf\u6027\u5c42\u540e\u76f8\u52a0\uff09\u3002\n### 4.2 \u524d\u5411\u4f2a\u4ee3\u7801\n```\n# \u8f93\u5165: \u5f52\u4e00\u5316\u5386\u53f2 X_hist = x_{t-P+1:t}  (shape P\u00d7D)\uff1b\u8fd4\u56de\u9884\u6d4b \\hat{X}_{t+1:t+H}\ndef forward(X_hist, t, C, backbone, w, L):\n    idx_hist = arange(t-P+1, t+1)\n    c_hist   = C[(idx_hist + L) % w]              # \u6309\u76f8\u4f4d\u67e5\u8868\uff08\u542b L \u504f\u79fb\uff0c\u89c1 \u03c6\uff09\n    R        = X_hist - c_hist                    # \u5468\u671f\u6b8b\u5dee r = x \u2212 c\n    R_fut    = backbone(R)                        # \u9884\u6d4b\u672a\u6765\u6b8b\u5dee (H\u00d7D)\n    idx_fut  = arange(t+1, t+H+1)\n    c_fut    = C[(idx_fut + L) % w]               # \u672a\u6765\u76f8\u4f4d\u5faa\u73af\u7279\u5f81\n    return R_fut + c_fut                          # \u53e0\u52a0\u8f93\u51fa\n```\n- \u8bad\u7ec3\u635f\u5931\uff1aMSE\uff08\u5f52\u4e00\u5316\u5c3a\u5ea6\uff0c\u89c1 \u00a76\uff09\uff1bMAE \u540c\u6b65\u8bb0\u5f55\u3002\n### 4.3 \u8bad\u7ec3\u5faa\u73af\u4f2a\u4ee3\u7801\n```\nfor seed in [0,1,2,3,4]:\n    set_seed(seed)\n    for each series:\n        mu,sig = mean/std(train_portion); Xnorm = (X-mu)/sig     # \u6bcf\u5e8f\u5217\u72ec\u7acb z-score\n        build train/val windows from Xnorm                      # \u00a73.3 \u5212\u5206\uff0cstride=H\n    model = CycleNet(w, D, backbone=linear|DLinear)\n    opt = Adam(model.params, lr=1e-3, weight_decay=1e-5)\n    sched = CosineAnnealingLR(opt, T_max=100)\n    for epoch in 1..100:\n        for batch in train_windows: loss = MSE(model(batch.x), batch.y); opt.step()\n        val_mse = MSE on val_windows\uff08\u5f52\u4e00\u5316\u5c3a\u5ea6\uff09\n        if val_mse best: \u4fdd\u5b58 best.pt\n        if no improve 10 epochs: break\n    # \u8bc4\u4f30: \u7528 best.pt \u5728 test \u6bb5\u9010\u7a97\u53e3\u9884\u6d4b \u2192 \u53cd\u5f52\u4e00\u5316 \\hat{x}=(\\hat{x}_norm*sig+mu)\n    # \u8bb0\u5f55 test MSE/MAE\uff08\u539f\u59cb\u5c3a\u5ea6\uff0c\u89c1 \u00a76\uff09\nreport mean\u00b1std over 5 seeds for every metric\n```\n\n## 5. \u57fa\u7ebf\u5b9a\u4e49\uff08\u7cbe\u786e\uff09\n1. **NoCycle\uff08cycle-free \u6d88\u878d/\u57fa\u7ebf\uff09**\uff1a\u4e0e CycleNet \u540c\u9aa8\u5e72\u3001\u540c\u8bad\u7ec3\u534f\u8bae\uff0c\u4f46**\u53bb\u6389\u5faa\u73af\u8868\u4e0e\u6b8b\u5dee\u73af\u8282**\uff1a`hat_x = B(X_hist)`\uff08\u9aa8\u5e72\u76f4\u63a5\u9884\u6d4b\u5f52\u4e00\u5316\u5e8f\u5217\uff09\u3002\u9694\u79bb\u300c\u663e\u5f0f\u5468\u671f\u5efa\u6a21\u300d\u7684\u8d21\u732e\u3002\n2. **DLinear\uff08\u72ec\u7acb\u57fa\u7ebf\uff09**\uff1a\u6807\u51c6 DLinear\uff0c\u5386\u53f2\u7a97\uff08\u975e\u6b8b\u5dee\uff09\u5206\u89e3\u4e3a\u8d8b\u52bf/\u5b63\u8282\u5e76\u9884\u6d4b\uff1b\u8bad\u7ec3\u534f\u8bae\u3001\u79cd\u5b50\u4e0e CycleNet \u5168\u540c\u3002\n3. **Seasonal-naive\uff08\u975e\u53c2\u6570\uff09**\uff1a\u6a21\u677f=\u6700\u8fd1\u4e00\u4e2a\u5468\u671f `x_{t-w+1:t}`\uff0c\u9884\u6d4b `\\hat{x}_{t+j} = template[(j-1) mod w]`\uff08j=1..H\uff1bH>w \u65f6\u5faa\u73af\u590d\u5236\u6a21\u677f\uff09\u3002\n4. **Persistent\uff08\u975e\u53c2\u6570\uff09**\uff1a`\\hat{x}_{t+j} = x_t`\uff08\u6700\u540e\u503c\u91cd\u590d\uff09\u3002\n- \u9644\u52a0\u6d88\u878d **FrozenCycle**\uff1a\u4fdd\u7559\u6b8b\u5dee\u7ba1\u7ebf\uff0c\u4f46 **C \u51bb\u7ed3\u4e3a\u968f\u673a\u521d\u59cb\u5316**\uff08\u4e0d\u53c2\u4e0e\u68af\u5ea6\u66f4\u65b0\uff0c\u4ec5\u9aa8\u5e72\u8bad\u7ec3\uff09\u2192 \u9a8c\u8bc1\u5faa\u73af\u7279\u5f81\u5fc5\u987b\u8054\u5408\u5b66\u4e60\u3002\n\n## 6. \u8bc4\u4ef7\u6307\u6807\uff08\u4e00\u81f4\u53e3\u5f84\uff09\n- \u5148\u5bf9\u6bcf\u4e2a\u6d4b\u8bd5\u7a97\u53e3\u9884\u6d4b\u53cd\u5f52\u4e00\u5316\u5230\u539f\u5c3a\u5ea6\uff0c\u518d\u8ba1\u7b97\uff1a`MSE = mean_{t,j,c}(x_tj \u2212 xhat_tj)^2`\uff0c`MAE = mean|x_tj \u2212 xhat_tj|`\u3002\n- \u62a5\u544a\uff1a\u539f\u59cb\u5c3a\u5ea6 MSE/MAE\uff08\u4e3b\u62a5\u544a\uff09+ \u5f52\u4e00\u5316\u5c3a\u5ea6 MSE\uff08\u8de8\u5e8f\u5217\u53ef\u6bd4\u526f\u8868\uff09\u3002\u591a seed \u7ed9 mean\u00b1std\u3002\u76f8\u5bf9\u63d0\u5347 `(MSE_base \u2212 MSE_CN)/MSE_base\u00d7100%`\u3002\n\n## 7. \u63a7\u5236\u53d8\u91cf\u6e05\u5355\uff08\u5f3a\u5236\uff0c\u6240\u6709\u65b9\u6cd5/\u79cd\u5b50\u5b8c\u5168\u4e00\u81f4\uff09\n- \u540c\u4e00 train/val/test \u5212\u5206\uff1b\u540c\u4e00 \u03bc,\u03c3\uff1b\u540c\u4e00 MSE \u635f\u5931\uff1b\u540c\u4e00\u4f18\u5316\u5668(Adam lr=1e-3, wd=1e-5)\u4e0e\u8c03\u5ea6(Cosine 100)\u3001\u65e9\u505c(patience=10)\uff1b\u540c\u4e00 batch size(128) \u4e0e\u8f93\u5165 P/H\uff1b\u540c\u4e00\u968f\u673a\u79cd\u5b50\u96c6 {0,1,2,3,4}\uff1b\u540c\u4e00\u6307\u6807\u5b9e\u73b0\u4ee3\u7801\uff1b\u6a21\u578b\u9009\u62e9\u4e25\u683c\u57fa\u4e8e val\uff0ctest \u4ec5\u8bc4\u4f30\u4e00\u6b21\u3002\n- \u6ce8\uff1a\u975e\u53c2\u6570\u57fa\u7ebf\uff08Seasonal-naive/Persistent\uff09\u65e0\u8bad\u7ec3\uff0c\u4f46\u7528\u540c\u4e00\u5212\u5206\u4e0e\u540c\u4e00\u6307\u6807\u4ee3\u7801\uff1b\"\u540c\u4f18\u5316\u5668\"\u6761\u6b3e\u4ec5\u7ea6\u675f\u53ef\u8bad\u7ec3\u6a21\u578b\u3002\n\n## 8. \u6d88\u878d\u4e0e\u654f\u611f\u6027\uff08\u9884\u671f\u89e3\u8bfb\u903b\u8f91 \u2192 \u5747\u4e3a\u5f85\u9a8c\u8bc1\u5047\u8bbe\uff09\n\u5728\u4ee3\u8868\u5355\u5143\u683c\uff08w=24, SNR=1.0, \u5355\u53d8\u91cf, \u5e73\u7a33, H=48, seed \u56fa\u5b9a\u4e3a 0 \u5916\u52a0 5-seed \u590d\u6838\uff09\u4e0a\u6267\u884c\uff1a\n- **AB1 \u5468\u671f\u957f\u5ea6\u504f\u5dee**\uff1aw' \u2208 {w\u2212\u0394, w, w+\u0394, 2w, w/2}\uff08\u0394=4\uff09\u3002\u89e3\u8bfb\u5047\u8bbe\uff1aw'=w \u65f6 test MSE \u5e94\u6700\u4f4e\uff08\u6b8b\u5dee\u4e2d\u6b8b\u7559\u5468\u671f\u6027\u6700\u5c11\uff09\uff1bw/2 \u628a\u4e24\u76f8\u4f4d\u5408\u5e76\u5bfc\u81f4\u6700\u5dee\uff1b2w \u56e0\u8c10\u6ce2\u7ed3\u6784\uff08\u57fa\u9891+\u4e00\u6b21\u8c10\u6ce2\uff09\u53ef\u80fd\u8fd1\u4e4e\u7b49\u4ef7\u6216\u7565\u5dee\u3002\u6b64\u4e3a\u673a\u5236\u9a8c\u8bc1\uff0c\u975e\u7ed3\u8bba\u3002\n- **AB2 lag \u504f\u79fb**\uff1aL \u2208 {0, +1, \u22121, +w/2, \u2212w/2}\u3002\u89e3\u8bfb\u5047\u8bbe\uff1a\u5408\u6210\u6570\u636e\u76f8\u4f4d\u5df2\u77e5\u4e14\u5e73\u7a33\uff0cL \u5f71\u54cd\u5e94\u5c0f\uff1b\u82e5\u6f02\u79fb/\u76f8\u4f4d\u9519\u4f4d\u6570\u636e\uff08drift=True\uff09\u51fa\u73b0\uff0c\u5219 L \u53ef\u80fd\u663e\u8457 \u2192 \u7528\u4e8e\u5224\u65ad\u76f8\u4f4d\u5bf9\u9f50\u654f\u611f\u6027\u3002\n- **AB3 \u9aa8\u5e72\u66ff\u6362**\uff1alinear vs DLinear \u5206\u522b\u5305\u5728 CycleNet \u91cc\uff0c\u5bf9\u7167\u7ec4\u4e3a\u5bf9\u5e94 NoCycle \u9aa8\u5e72 \u2192 \u5206\u79bb\u300c\u5468\u671f\u6a21\u5757\u589e\u76ca\u300d\u4e0e\u300c\u9aa8\u5e72\u80fd\u529b\u589e\u76ca\u300d\uff08RQ1/RQ3 \u5f52\u56e0\uff09\u3002\n- **AB4 FrozenCycle**\uff1aC \u662f\u5426\u5fc5\u987b\u53ef\u5b66\u4e60\uff08\u8054\u5408\u8bad\u7ec3\u7684\u5fc5\u8981\u6027\uff09\u3002\n\n## 9. \u5b8c\u6574\u5b9e\u9a8c\u77e9\u9635\uff08M=\u5fc5\u505a\uff0cO=\u53ef\u9009\u5206\u652f\uff09\n**\u4e3b\u5bf9\u7167\u77e9\u9635\uff08\u5fc5\u505a M1\u2013M16\uff09**\uff1a\u56e0\u5b50 = w{24,168} \u00d7 SNR{0.1,1.0} \u00d7 H \u5173\u7cfb{H<w, H>w} \u00d7 {\u5355\u53d8\u91cf, \u5e73\u7a33} = 2\u00d72\u00d72\u00d72=16 \u5355\u5143\u683c\uff1b\u6bcf\u683c\u65b9\u6cd5 = {CycleNet(linear, w \u6b63\u786e), NoCycle-linear, DLinear, Seasonal-naive, Persistent} \u00d7 5 seeds\u3002H \u53d6\u503c\uff1aw=24 \u2192 H\u2208{12(H<w), 48(H>w)}\uff1bw=168 \u2192 H\u2208{48(H<w), 336(H>w)}\u3002\n**\u6d88\u878d\u77e9\u9635\uff08\u5fc5\u505a\uff09**\uff1aAB1\u00d75\u3001AB2\u00d75\u3001AB3\uff08linear/DLinear \u5404 \u00d7[CycleNet, NoCycle]\u00d75 seeds\uff09\u3001AB4\u00d75\uff0c\u5747\u5728\u4ee3\u8868\u5355\u5143\u683c\u3002\n**\u53ef\u9009\u6269\u5c55\uff08O\uff09**\uff1a\n- O1 \u591a\u53d8\u91cf\uff08D=8\uff09\u91cd\u8dd1 M \u7684 4 \u4e2a\u4ee3